            continue
        yield number, line


def parse_date(value: str, number: int) -> datetime.date:
    match = _DATE.fullmatch(value)
    if not match:
        raise ParseError(number, "bad date %r (want YYYY-MM-DD)" % value)
    try:
        return datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
    except ValueError:
        raise ParseError(number, "no such date %r" % value)


def _to_int(value: str, number: int, what: str) -> int:
    try:
        return int(value)
    except ValueError:
        raise ParseError(number, "%s %r is too large" % (what, value[:20]))


def parse_catalog(text: str) -> Dict[str, Product]:
    catalog = {}  # type: Dict[str, Product]
    for number, line in numbered_lines(text):
        fields = [f.strip() for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(number, "expected 4 or 5 fields separated by '|', found %d" % len(fields))
        sku, name, price, reorder = fields[:4]
        if not _SKU.fullmatch(sku):
            raise ParseError(number, "bad SKU %r" % sku)
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if not name:
            raise ParseError(number, "empty name")
        if not _PRICE.fullmatch(price):
            raise ParseError(number, "bad price %r" % price)
        value = Decimal(price).quantize(_CENT, context=_MONEY)
        if value < _CENT:
            raise ParseError(number, "price %r is below 0.01" % price)
        if not _UINT.fullmatch(reorder):
            raise ParseError(number, "bad reorder level %r" % reorder)
        reorder_n = _to_int(reorder, number, "reorder level")
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4]
            if not tax.isascii() or tax.lower() not in TAXES:
                raise ParseError(number, "bad tax %r (want standard, reduced or zero)" % tax)
            tax = tax.lower()
        catalog[sku] = Product(sku, name, value, reorder_n, tax)
    return catalog


def parse_movements(text: str, catalog: Dict[str, Product]) -> List[Movement]:
    movements = []  # type: List[Movement]
    lines = []  # type: List[int]
    for number, line in numbered_lines(text):
        fields = _SEP.split(line.strip(" \t"), maxsplit=3)
        if len(fields) < 3:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date = parse_date(fields[0], number)
        if not _SKU.fullmatch(fields[1]) or fields[1].upper() not in catalog:
            raise ParseError(number, "unknown SKU %r" % fields[1])
        if not _SIGNED.fullmatch(fields[2]):
            raise ParseError(number, "bad quantity %r" % fields[2])
        quantity = _to_int(fields[2], number, "quantity")
        if quantity == 0:
            raise ParseError(number, "quantity may not be zero")
        note = fields[3].strip() if len(fields) == 4 else ""
        movements.append(Movement(date, fields[1].upper(), quantity, note))
        lines.append(number)
    bad = first_below_zero(movements)
    if bad is not None:
        raise ParseError(lines[bad], "stock of %s would go below zero" % movements[bad].sku)
    return movements


def parse_orders(text: str, catalog: Dict[str, Product]) -> List[Order]:
    orders = []  # type: List[Order]
    seen = set()
    for number, line in numbered_lines(text):
        fields = _SEP.split(line.strip(" \t"))
        if len(fields) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES (4 fields), found %d" % len(fields))
        order_id, date_text, customer, lines_text = fields
        if not _ORDER_ID.fullmatch(order_id):
            raise ParseError(number, "bad order number %r" % order_id)
        order_id = order_id.upper()
        if order_id in seen:
            raise ParseError(number, "duplicate order %s" % order_id)
        date = parse_date(date_text, number)
        pairs = []  # type: List[Tuple[str, int]]
        used = set()
        for item in lines_text.split(","):
            match = _ORDER_LINE.fullmatch(item)
            if not match:
                raise ParseError(number, "bad order line %r (want SKU*QUANTITY)" % item)
            sku = match.group(1).upper()
            if sku not in catalog:
                raise ParseError(number, "unknown SKU %r" % match.group(1))
            if sku in used:
                raise ParseError(number, "SKU %s appears twice in the order" % sku)
            quantity = _to_int(match.group(2), number, "quantity")
            if quantity < 1:
                raise ParseError(number, "quantity must be at least 1")
            used.add(sku)
            pairs.append((sku, quantity))
        seen.add(order_id)
        orders.append(Order(order_id, date, customer, pairs))
    return orders
"""Stock levels, status, low stock, history and new-movement validation."""

from typing import Dict, Iterable, List, Optional, Tuple

from .models import Movement, Product


def counting_order(movements: Iterable[Movement]) -> List[Movement]:
    """Movements in the order they count: by date, file order within a day."""
    return sorted(movements, key=lambda m: m.date)


def stock_levels(catalog: Dict[str, Product], movements: Iterable[Movement]) -> Dict[str, int]:
    """SKU -> quantity on the shelf, for every product in the catalogue."""
    levels = {sku: 0 for sku in catalog}
    for move in movements:
        if move.sku in levels:
            levels[move.sku] += move.quantity
    return levels


def status(product: Product, onhand: int) -> str:
    if onhand <= 0:
        return "out"
    if onhand <= product.reorder:
        return "low"
    return "ok"


def buy_quantity(product: Product, onhand: int) -> int:
    return max(1, 2 * product.reorder - onhand)


def first_below_zero(movements: List[Movement]) -> Optional[int]:
    """Index (in the given list) of the movement that first takes any stock
    below zero in counting order, or None."""
    order = sorted(range(len(movements)), key=lambda i: movements[i].date)
    balances = {}  # type: Dict[str, int]
    for i in order:
        move = movements[i]
        balance = balances.get(move.sku, 0) + move.quantity
        if balance < 0:
            return i
        balances[move.sku] = balance
    return None


def history(movements: Iterable[Movement], sku: str) -> List[Tuple[Movement, int]]:
    """Movements of one SKU in counting order, each with the balance after it."""
    rows = []
    balance = 0
    for move in counting_order(movements):
        if move.sku == sku:
            balance += move.quantity
            rows.append((move, balance))
    return rows


def would_go_negative(movements: Iterable[Movement], new: Movement) -> bool:
    """True if appending `new` to the file would break the stock rule."""
    return first_below_zero(list(movements) + [new]) is not None
"""Shipments, order status, invoices and the report rows."""

import datetime
from decimal import Decimal
from typing import Dict, Iterable, List, Optional, Tuple

from .models import Movement, Order
from .shelves import counting_order


def shipped_so_far(order: Order, movements: Iterable[Movement]) -> Dict[str, int]:
    """SKU -> units already sent for this order (capped at the ordered quantity)."""
    note = "order " + order.id
    sent = {sku: 0 for sku, _ in order.lines}
    for move in movements:
        if move.quantity < 0 and move.note == note and move.sku in sent:
            sent[move.sku] += -move.quantity
    return {sku: min(sent[sku], qty) for sku, qty in order.lines}


def order_status(order: Order, shipped: Dict[str, int]) -> str:
    if all(shipped[sku] >= qty for sku, qty in order.lines):
        return "complete"
    if not any(shipped[sku] for sku, _ in order.lines):
        return "open"
    return "partial"


def shippable(sku: str, movements: Iterable[Movement], date: datetime.date) -> int:
    """Most units of `sku` that can leave on `date` without any movement,
    on or after that date, taking the stock below zero."""
    balance = 0
    at_date = 0
    later_min = None  # type: Optional[int]
    for move in counting_order(movements):
        if move.sku != sku:
            continue
        balance += move.quantity
        if move.date <= date:
            at_date = balance
        elif later_min is None or balance < later_min:
            later_min = balance
    cap = at_date if later_min is None else min(at_date, later_min)
    return max(0, cap)


def plan_shipment(order: Order, date: datetime.date, movements: List[Movement]) -> List[Tuple[str, int]]:
    """(sku, units to ship now) per order line, in order-line order."""
    shipped = shipped_so_far(order, movements)
    return [
        (sku, min(qty - shipped[sku], shippable(sku, movements, date)))
        for sku, qty in order.lines
    ]


def shipped_order(order: Order, shipped: Dict[str, int]) -> Order:
    """The order restricted to what has shipped (lines with nothing dropped)."""
    lines = [(sku, shipped[sku]) for sku, _ in order.lines if shipped[sku] > 0]
    return Order(order.id, order.date, order.customer, lines)

"""Exact-to-the-penny order pricing (all arithmetic on whole pence)."""

from decimal import Context, Decimal, ROUND_HALF_UP
from typing import Dict, List

from .models import Order, Product, Quote, QuoteLine

_CTX = Context(prec=100000, rounding=ROUND_HALF_UP, Emax=999999999, Emin=-999999999)
_RATES = {"standard": 20, "reduced": 5, "zero": 0}


def _pct(pence: int, percent: int) -> int:
    """percent of pence, rounded half up (pence >= 0)."""
    return (pence * percent + 50) // 100


def _money(pence: int) -> Decimal:
    return _CTX.scaleb(Decimal(pence), -2)


def allocate_discount(discount: int, nets: List[int]) -> List[int]:
    """Share `discount` pence over lines in proportion to `nets` (pence): each
    share rounds down, leftover pence go to the biggest fractional losses,
    earlier line first on a tie."""
    total = sum(nets)
    if not discount or not total:
        return [0] * len(nets)
    parts = [divmod(discount * net, total) for net in nets]
    shares = [p[0] for p in parts]
    leftover = discount - sum(shares)
    for i in sorted(range(len(nets)), key=lambda i: (-parts[i][1], i))[:leftover]:
        shares[i] += 1
    return shares


def price_order(order: Order, catalog: Dict[str, Product]) -> Quote:
    rows = []  # (sku, qty, unit, gross, discount, net) in pence
    for sku, qty in order.lines:
        product = catalog[sku]
        unit = int(_CTX.multiply(product.price, 100))
        gross = qty * unit
        percent = 10 if qty >= 50 else 5 if qty >= 10 else 0
        discount = _pct(gross, percent)
        rows.append((sku, qty, unit, gross, discount, gross - discount))

    subtotal = sum(r[5] for r in rows)
    order_discount = _pct(subtotal, 3) if subtotal >= 50000 else 0

    shares = allocate_discount(order_discount, [r[5] for r in rows])

    tax = 0
    for row, share in zip(rows, shares):
        tax += _pct(row[5] - share, _RATES[catalog[row[0]].tax])

    lines = [
        QuoteLine(sku, qty, _money(unit), _money(gross), _money(-discount), _money(net))
        for sku, qty, unit, gross, discount, net in rows
    ]  # type: List[QuoteLine]
    return Quote(
        lines,
        _money(subtotal),
        _money(-order_discount),
        _money(tax),
        _money(subtotal - order_discount + tax),
    )
