content.content:
"""The `stockroom` command."""

import csv
import datetime
import io
import json
import os
import re
import sys
from typing import Dict, List, NamedTuple, Optional

from . import orders as orders_mod
from . import shelves
from .models import Movement, Order, Quote
from .parsing import ParseError, parse_catalog, parse_date, parse_movements, parse_orders
from .pricing import price_order

CATALOG, MOVEMENTS, ORDERS = "catalog.txt", "movements.txt", "orders.txt"

# command -> (files needed, positional args min, max, options allowed)
COMMANDS = {
    "stock": ((CATALOG, MOVEMENTS), 0, 0, ("json",)),
    "low": ((CATALOG, MOVEMENTS), 0, 0, ("json",)),
    "history": ((CATALOG, MOVEMENTS), 1, 1, ("json",)),
    "receive": ((CATALOG, MOVEMENTS), 3, 4, ()),
    "ship": ((CATALOG, MOVEMENTS), 3, 4, ()),
    "quote": ((CATALOG, ORDERS), 1, 1, ("json",)),
    "fulfil": ((CATALOG, MOVEMENTS, ORDERS), 2, 2, ()),
    "invoice": ((CATALOG, MOVEMENTS, ORDERS), 1, 1, ("json",)),
    "report": ((CATALOG, MOVEMENTS, ORDERS), 0, 0, ("format",)),
}

_SKU = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_ORDER_ID = re.compile(r"[Ss][Oo]-[0-9]+")
_UINT = re.compile(r"[0-9]+")


class UsageError(Exception):
    """Bad command line -> exit 2."""


class FileProblem(Exception):
    """Unreadable file or directory -> exit 2."""


class Refused(Exception):
    """A data mistake or a refused request -> exit 1."""


class Command(NamedTuple):
    name: str
    args: List[str]
    directory: str
    json: bool
    format: str


def parse_command_line(argv: List[str]) -> Command:
    directory = "."
    rest = []  # type: List[str]
    i = 0
    while i < len(argv):
        token = argv[i]
        if token == "--dir":
            if i + 1 >= len(argv):
                raise UsageError("--dir needs a value")
            directory = argv[i + 1]
            if directory == "":
                raise UsageError("--dir needs a value")
            i += 2
            continue
        if token.startswith("--dir="):
            directory = token[len("--dir="):]
            if directory == "":
                raise UsageError("--dir needs a value")
        else:
            rest.append(token)
        i += 1
    if not rest:
        raise UsageError("no command given")
    name = rest[0]
    if name not in COMMANDS:
        raise UsageError("unknown command %r" % name)
    _files, low, high, options = COMMANDS[name]
    args = []  # type: List[str]
    want_json = False
    fmt = "text"
    tokens = rest[1:]
    free = not options
    j = 0
    options_over = False
    while j < len(tokens):
        token = tokens[j]
        j += 1
        if free or options_over or not token.startswith("-") or token == "-":
            args.append(token)
        elif token == "--":
            options_over = True
        elif token == "--json" and "json" in options:
            want_json = True
        elif "format" in options and (token == "--format" or token.startswith("--format=")):
            if token == "--format":
                if j >= len(tokens):
                    raise UsageError("--format needs a value")
                value = tokens[j]
                j += 1
            else:
                value = token[len("--format="):]
            if value not in ("text", "csv", "json"):
                raise UsageError("bad --format value %r (want text, csv or json)" % value)
            fmt = value
        else:
            raise UsageError("unknown option %r" % token)
    if not low <= len(args) <= high:
        raise UsageError("wrong number of arguments for %s" % name)
    date_arg = {"receive": 0, "ship": 0, "fulfil": 1}.get(name)
    if date_arg is not None:
        try:
            parse_date(args[date_arg], 0)
        except ParseError:
            raise UsageError("bad date %r (want YYYY-MM-DD)" % args[date_arg])
    return Command(name, args, directory, want_json, fmt)


def read_text(directory: str, name: str, required: bool) -> str:
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise FileProblem("%s: file not found" % name)
        return ""
    except OSError as exc:
        raise FileProblem("%s: %s" % (name, exc.strerror or exc))
    try:
        return data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise FileProblem("%s: not valid UTF-8" % name)


def parse_file(name: str, parser, *args):
    try:
        return parser(*args)
    except ParseError as exc:
        raise Refused("%s: %s" % (name, exc))


class Data(NamedTuple):
    directory: str
    catalog: dict
    movements: List[Movement]
    orders: List[Order]


def load(cmd: Command) -> Data:
    files = COMMANDS[cmd.name][0]
    if not os.path.isdir(cmd.directory):
        raise FileProblem("%s: not a directory" % cmd.directory)
    texts = {name: read_text(cmd.directory, name, name == CATALOG) for name in files}
    catalog = parse_file(CATALOG, parse_catalog, texts[CATALOG])
    movements = []  # type: List[Movement]
    orders = []  # type: List[Order]
    if MOVEMENTS in texts:
        movements = parse_file(MOVEMENTS, parse_movements, texts[MOVEMENTS], catalog)
    if ORDERS in texts:
        orders = parse_file(ORDERS, parse_orders, texts[ORDERS], catalog)
    return Data(cmd.directory, catalog, movements, orders)


def append_lines(directory: str, name: str, lines: List[str]) -> None:
    path = os.path.join(directory, name)
    prefix = b""
    try:
        with open(path, "rb") as handle:
            handle.seek(0, os.SEEK_END)
            if handle.tell() > 0:
                handle.seek(-1, os.SEEK_END)
                if handle.read(1) != b"\n":
                    prefix = b"\n"
    except FileNotFoundError:
        pass
    except OSError as exc:
        raise FileProblem("%s: %s" % (name, exc.strerror or exc))
    payload = prefix + "".join(line + "\n" for line in lines).encode("utf-8")
    try:
        with open(path, "ab") as handle:
            handle.write(payload)
    except OSError as exc:
        raise FileProblem("%s: %s" % (name, exc.strerror or exc))


# ---------------------------------------------------------------- formatting

def amount(value) -> str:
    return format(value, "f")


def as_json(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def lookup_sku(text: str, catalog: dict) -> str:
    if _SKU.fullmatch(text) and text.upper() in catalog:
        return text.upper()
    raise Refused("unknown SKU %s" % text)


def lookup_order(text: str, orders: List[Order]) -> Order:
    if _ORDER_ID.fullmatch(text):
        for order in orders:
            if order.id == text.upper():
                return order
    raise Refused("unknown order %s" % text)


def render_quote(order: Order, quote: Quote, as_text: bool, prefix: str = "") -> str:
    if not as_text:
        return as_json({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": l.sku,
                    "quantity": l.quantity,
                    "unit": amount(l.unit),
                    "gross": amount(l.gross),
                    "discount": amount(l.discount),
                    "net": amount(l.net),
                }
                for l in quote.lines
            ],
            "subtotal": amount(quote.subtotal),
            "order_discount": amount(quote.order_discount),
            "tax": amount(quote.tax),
            "total": amount(quote.total),
        })
    out = ["%s%s %s %s" % (prefix, order.id, order.date.isoformat(), order.customer)]
    for l in quote.lines:
        out.append("%s %d %s %s %s %s" % (
            l.sku, l.quantity, amount(l.unit), amount(l.gross), amount(l.discount), amount(l.net)))
    out.append("subtotal " + amount(quote.subtotal))
    out.append("order discount " + amount(quote.order_discount))
    out.append("tax " + amount(quote.tax))
    out.append("total " + amount(quote.total))
    return "\n".join(out) + "\n"


# ------------------------------------------------------------------ commands

def do_stock(cmd: Command, data: Data) -> str:
    levels = shelves.stock_levels(data.catalog, data.movements)
    rows = [(sku, data.catalog[sku], levels[sku]) for sku in sorted(data.catalog)]
    if cmd.json:
        return as_json([
            {"sku": sku, "name": p.name, "onhand": n, "status": shelves.status(p, n)}
            for sku, p, n in rows])
    return "".join("%s %d %s %s\n" % (sku, n, shelves.status(p, n), p.name) for sku, p, n in rows)


def do_low(cmd: Command, data: Data) -> str:
    levels = shelves.stock_levels(data.catalog, data.movements)
    rows = [
        (sku, levels[sku], data.catalog[sku].reorder, shelves.buy_quantity(data.catalog[sku], levels[sku]))
        for sku in sorted(data.catalog)
        if shelves.status(data.catalog[sku], levels[sku]) != "ok"
    ]
    if cmd.json:
        return as_json([
            {"sku": s, "onhand": n, "reorder": r, "buy": b} for s, n, r, b in rows])
    return "".join("%s %d %d %d\n" % row for row in rows)


def do_history(cmd: Command, data: Data) -> str:
    sku = lookup_sku(cmd.args[0], data.catalog)
    rows = shelves.history(data.movements, sku)
    if cmd.json:
        return as_json([
            {"date": m.date.isoformat(), "delta": "%+d" % m.quantity, "balance": b, "note": m.note}
            for m, b in rows])
    return "".join(
        "%s %+d %d%s\n" % (m.date.isoformat(), m.quantity, b, " " + m.note if m.note else "")
        for m, b in rows)


def do_move(cmd: Command, data: Data) -> str:
    date_text, sku_text, qty_text = cmd.args[:3]
    note = cmd.args[3] if len(cmd.args) == 4 else ""
    sku = lookup_sku(sku_text, data.catalog)
    if not _UINT.fullmatch(qty_text):
        raise Refused("bad quantity %r (want a whole number of 1 or more)" % qty_text)
    try:
        qty = int(qty_text)
    except ValueError:
        raise Refused("quantity is too large")
    if qty < 1:
        raise Refused("bad quantity %r (want a whole number of 1 or more)" % qty_text)
    if "\n" in note or "\r" in note:
        raise Refused("a note may not contain a line break")
    note = note.strip()
    try:
        note.encode("utf-8")
    except UnicodeEncodeError:
        raise Refused("note is not valid text")
    delta = qty if cmd.name == "receive" else -qty
    date = datetime.date.fromisoformat(date_text)
    if shelves.would_go_negative(data.movements, Movement(date, sku, delta, note)):
        raise Refused("stock of %s would go below zero" % sku)
    line = "%s %s %+d%s" % (date_text, sku, delta, " " + note if note else "")
    append_lines(data.directory, MOVEMENTS, [line])
    return line + "\n"


def do_quote(cmd: Command, data: Data) -> str:
    order = lookup_order(cmd.args[0], data.orders)
    return render_quote(order, price_order(order, data.catalog), not cmd.json)


def do_fulfil(cmd: Command, data: Data) -> str:
    order = lookup_order(cmd.args[0], data.orders)
    date = datetime.date.fromisoformat(cmd.args[1])
    if date < order.date:
        raise Refused("%s is dated %s; cannot fulfil on %s" % (order.id, order.date.isoformat(), cmd.args[1]))
    shipped = orders_mod.shipped_so_far(order, data.movements)
    plan = orders_mod.plan_shipment(order, date, data.movements)
    new_lines = ["%s %s -%d order %s" % (cmd.args[1], sku, n, order.id) for sku, n in plan if n > 0]
    if new_lines:
        append_lines(data.directory, MOVEMENTS, new_lines)
    after = {sku: shipped[sku] + n for sku, n in plan}
    out = []
    for sku, qty in order.lines:
        out.append("%s shipped %d backordered %d" % (sku, dict(plan)[sku], qty - after[sku]))
    out.append("status " + orders_mod.order_status(order, after))
    return "\n".join(out) + "\n"


def do_invoice(cmd: Command, data: Data) -> str:
    order = lookup_order(cmd.args[0], data.orders)
    shipped = orders_mod.shipped_so_far(order, data.movements)
    sent = orders_mod.shipped_order(order, shipped)
    if not sent.lines:
        raise Refused("nothing shipped for %s" % order.id)
    return render_quote(sent, price_order(sent, data.catalog), not cmd.json, "invoice ")


def order_sort_key(order: Order):
    """Order date, then order number; equal numbers (SO-7, SO-007) fall back to the id string.

    The number is compared as (digit count, digits) after stripping zeros, which is numeric
    order without int(), so a huge number cannot hit the integer string-conversion limit.
    """
    digits = order.id.split("-", 1)[1].lstrip("0")
    return (order.date, len(digits), digits, order.id)


def do_report(cmd: Command, data: Data) -> str:
    rows = []
    for order in sorted(data.orders, key=order_sort_key):
        shipped = orders_mod.shipped_so_far(order, data.movements)
        sent = orders_mod.shipped_order(order, shipped)
        invoiced = price_order(sent, data.catalog).total if sent.lines else None
        rows.append({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "status": orders_mod.order_status(order, shipped),
            "ordered": sum(q for _, q in order.lines),
            "shipped": sum(shipped.values()),
            "quoted": amount(price_order(order, data.catalog).total),
            "invoiced": amount(invoiced) if invoiced is not None else "0.00",
        })
    if cmd.format == "json":
        return as_json(rows)
    if cmd.format == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        writer.writerow(keys)
        for row in rows:
            writer.writerow([row[k] for k in keys])
        return buffer.getvalue()
    return "".join(
        "%s %s %s %s %d/%d %s %s\n" % (
            r["order"], r["date"], r["customer"], r["status"],
            r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
        for r in rows)


HANDLERS = {
    "stock": do_stock,
    "low": do_low,
    "history": do_history,
    "receive": do_move,
    "ship": do_move,
    "quote": do_quote,
    "fulfil": do_fulfil,
    "invoice": do_invoice,
    "report": do_report,
}


# ---------------------------------------------------------------------- main

def emit(text: str) -> int:
    """Write stdout as UTF-8; a closed pipe ends quietly with status 0."""
    try:
        buffer = getattr(sys.stdout, "buffer", None)
        if buffer is not None:
            sys.stdout.flush()
            buffer.write(text.encode("utf-8"))
            buffer.flush()
        else:
            sys.stdout.write(text)
            sys.stdout.flush()
    except BrokenPipeError:
        silence_stdout()
        return 0
    except OSError as exc:
        silence_stdout()
        fail("cannot write output: %s" % (exc.strerror or exc))
        return 2
    return 0


def silence_stdout() -> None:
    """Point stdout at /dev/null so the exit-time flush cannot fail noisily."""
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def fail(message: str) -> None:
    try:
        sys.stderr.write("stockroom: %s\n" % message)
        sys.stderr.flush()
    except (OSError, ValueError):
        pass


def main(argv: Optional[List[str]] = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    try:
        cmd = parse_command_line(args)
        data = load(cmd)
        output = HANDLERS[cmd.name](cmd, data)
    except UsageError as exc:
        fail(str(exc))
        return 2
    except FileProblem as exc:
        fail(str(exc))
        return 2
    except Refused as exc:
        fail(str(exc))
        return 1
    return emit(output)

"""Text of the three data files -> records. Mistakes raise ParseError."""

import datetime
import re
from decimal import Context, Decimal, ROUND_HALF_UP
from typing import Dict, Iterator, List, Tuple

from .models import Movement, Order, Product
from .shelves import first_below_zero

_MONEY = Context(prec=100000, rounding=ROUND_HALF_UP, Emax=999999999, Emin=-999999999)
_CENT = Decimal("0.01")

_SKU = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_PRICE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
_UINT = re.compile(r"[0-9]+")
_SIGNED = re.compile(r"[+-]?[0-9]+")
_DATE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_ORDER_ID = re.compile(r"[Ss][Oo]-[0-9]+")
_ORDER_LINE = re.compile(r"([A-Za-z]{2,4}-[0-9]{3})\*([0-9]+)")
_SEP = re.compile(r"[ \t]+")

TAXES = ("standard", "reduced", "zero")


class ParseError(ValueError):
    """A mistake in a data file. `.line` is the 1-based line number."""

    def __init__(self, line: int, reason: str):
        self.line = line
        self.reason = reason
        super().__init__("line %d: %s" % (line, reason))

    def __reduce__(self):
        return (ParseError, (self.line, self.reason))


def numbered_lines(text: str) -> Iterator[Tuple[int, str]]:
    """(line number, content) for every real line; blank and comment lines
    are skipped but counted. Lines end at LF; one trailing CR is dropped."""
    if text.startswith("﻿"):
        text = text[1:]
    for number, raw in enumerate(text.split("\n"), 1):
        line = raw[:-1] if raw.endswith("\r") else raw
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        yield number, line


def parse_date(value: str, number: int) -> datetime.date:
    match = _DATE.fullmatch(value)
    if not match:
        raise ParseError(number, "bad date %r (want YYYY-MM-DD)" % value)
    try:
        return datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
    except ValueError:
        raise ParseError(number, "no such date %r" % value)


def _to_int(value: str, number: int, what: str) -> int:
    try:
        return int(value)
    except ValueError:
        raise ParseError(number, "%s %r is too large" % (what, value[:20]))


def parse_catalog(text: str) -> Dict[str, Product]:
    catalog = {}  # type: Dict[str, Product]
    for number, line in numbered_lines(text):
        fields = [f.strip() for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(number, "expected 4 or 5 fields separated by '|', found %d" % len(fields))
        sku, name, price, reorder = fields[:4]
        if not _SKU.fullmatch(sku):
            raise ParseError(number, "bad SKU %r" % sku)
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if not name:
            raise ParseError(number, "empty name")
        if not _PRICE.fullmatch(price):
            raise ParseError(number, "bad price %r" % price)
        value = Decimal(price).quantize(_CENT, context=_MONEY)
        if value < _CENT:
            raise ParseError(number, "price %r is below 0.01" % price)
        if not _UINT.fullmatch(reorder):
            raise ParseError(number, "bad reorder level %r" % reorder)
        reorder_n = _to_int(reorder, number, "reorder level")
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4]
            if not tax.isascii() or tax.lower() not in TAXES:
                raise ParseError(number, "bad tax %r (want standard, reduced or zero)" % tax)
            tax = tax.lower()
        catalog[sku] = Product(sku, name, value, reorder_n, tax)
    return catalog


def parse_movements(text: str, catalog: Dict[str, Product]) -> List[Movement]:
    movements = []  # type: List[Movement]
    lines = []  # type: List[int]
    for number, line in numbered_lines(text):
        fields = _SEP.split(line.strip(" \t"), maxsplit=3)
        if len(fields) < 3:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date = parse_date(fields[0], number)
        if not _SKU.fullmatch(fields[1]) or fields[1].upper() not in catalog:
            raise ParseError(number, "unknown SKU %r" % fields[1])
        if not _SIGNED.fullmatch(fields[2]):
            raise ParseError(number, "bad quantity %r" % fields[2])
        quantity = _to_int(fields[2], number, "quantity")
        if quantity == 0:
            raise ParseError(number, "quantity may not be zero")
        note = fields[3].strip() if len(fields) == 4 else ""
        movements.append(Movement(date, fields[1].upper(), quantity, note))
        lines.append(number)
    bad = first_below_zero(movements)
    if bad is not None:
        raise ParseError(lines[bad], "stock of %s would go below zero" % movements[bad].sku)
    return movements


def parse_orders(text: str, catalog: Dict[str, Product]) -> List[Order]:
    orders = []  # type: List[Order]
    seen = set()
    for number, line in numbered_lines(text):
        fields = _SEP.split(line.strip(" \t"))
        if len(fields) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES (4 fields), found %d" % len(fields))
        order_id, date_text, customer, lines_text = fields
        if not _ORDER_ID.fullmatch(order_id):
            raise ParseError(number, "bad order number %r" % order_id)
        order_id = order_id.upper()
        if order_id in seen:
            raise ParseError(number, "duplicate order %s" % order_id)
        date = parse_date(date_text, number)
        pairs = []  # type: List[Tuple[str, int]]
        used = set()
        for item in lines_text.split(","):
            match = _ORDER_LINE.fullmatch(item)
            if not match:
                raise ParseError(number, "bad order line %r (want SKU*QUANTITY)" % item)
            sku = match.group(1).upper()
            if sku not in catalog:
                raise ParseError(number, "unknown SKU %r" % match.group(1))
            if sku in used:
                raise ParseError(number, "SKU %s appears twice in the order" % sku)
            quantity = _to_int(match.group(2), number, "quantity")
            if quantity < 1:
                raise ParseError(number, "quantity must be at least 1")
            used.add(sku)
            pairs.append((sku, quantity))
        seen.add(order_id)
        orders.append(Order(order_id, date, customer, pairs))
    return orders
"""Stock levels, status, low stock, history and new-movement validation."""

from typing import Dict, Iterable, List, Optional, Tuple

from .models import Movement, Product


def counting_order(movements: Iterable[Movement]) -> List[Movement]:
    """Movements in the order they count: by date, file order within a day."""
    return sorted(movements, key=lambda m: m.date)


def stock_levels(catalog: Dict[str, Product], movements: Iterable[Movement]) -> Dict[str, int]:
    """SKU -> quantity on the shelf, for every product in the catalogue."""
    levels = {sku: 0 for sku in catalog}
    for move in movements:
        if move.sku in levels:
            levels[move.sku] += move.quantity
    return levels


def status(product: Product, onhand: int) -> str:
    if onhand <= 0:
        return "out"
    if onhand <= product.reorder:
        return "low"
    return "ok"


def buy_quantity(product: Product, onhand: int) -> int:
    return max(1, 2 * product.reorder - onhand)


def first_below_zero(movements: List[Movement]) -> Optional[int]:
    """Index (in the given list) of the movement that first takes any stock
    below zero in counting order, or None."""
    order = sorted(range(len(movements)), key=lambda i: movements[i].date)
    balances = {}  # type: Dict[str, int]
    for i in order:
        move = movements[i]
        balance = balances.get(move.sku, 0) + move.quantity
        if balance < 0:
            return i
        balances[move.sku] = balance
    return None


def history(movements: Iterable[Movement], sku: str) -> List[Tuple[Movement, int]]:
    """Movements of one SKU in counting order, each with the balance after it."""
    rows = []
    balance = 0
    for move in counting_order(movements):
        if move.sku == sku:
            balance += move.quantity
            rows.append((move, balance))
    return rows


def would_go_negative(movements: Iterable[Movement], new: Movement) -> bool:
    """True if appending `new` to the file would break the stock rule."""
    return first_below_zero(list(movements) + [new]) is not None
"""Shipments, order status, invoices and the report rows."""

import datetime
from decimal import Decimal
from typing import Dict, Iterable, List, Optional, Tuple

from .models import Movement, Order
from .shelves import counting_order


def shipped_so_far(order: Order, movements: Iterable[Movement]) -> Dict[str, int]:
    """SKU -> units already sent for this order (capped at the ordered quantity)."""
    note = "order " + order.id
    sent = {sku: 0 for sku, _ in order.lines}
    for move in movements:
        if move.quantity < 0 and move.note == note and move.sku in sent:
            sent[move.sku] += -move.quantity
    return {sku: min(sent[sku], qty) for sku, qty in order.lines}


def order_status(order: Order, shipped: Dict[str, int]) -> str:
    if all(shipped[sku] >= qty for sku, qty in order.lines):
        return "complete"
    if not any(shipped[sku] for sku, _ in order.lines):
        return "open"
    return "partial"


def shippable(sku: str, movements: Iterable[Movement], date: datetime.date) -> int:
    """Most units of `sku` that can leave on `date` without any movement,
    on or after that date, taking the stock below zero."""
    balance = 0
    at_date = 0
    later_min = None  # type: Optional[int]
    for move in counting_order(movements):
        if move.sku != sku:
            continue
        balance += move.quantity
        if move.date <= date:
            at_date = balance
        elif later_min is None or balance < later_min:
            later_min = balance
    cap = at_date if later_min is None else min(at_date, later_min)
    return max(0, cap)


def plan_shipment(order: Order, date: datetime.date, movements: List[Movement]) -> List[Tuple[str, int]]:
    """(sku, units to ship now) per order line, in order-line order."""
    shipped = shipped_so_far(order, movements)
    return [
        (sku, min(qty - shipped[sku], shippable(sku, movements, date)))
        for sku, qty in order.lines
    ]


def shipped_order(order: Order, shipped: Dict[str, int]) -> Order:
    """The order restricted to what has shipped (lines with nothing dropped)."""
    lines = [(sku, shipped[sku]) for sku, _ in order.lines if shipped[sku] > 0]
    return Order(order.id, order.date, order.customer, lines)

"""Exact-to-the-penny order pricing (all arithmetic on whole pence)."""

from decimal import Context, Decimal, ROUND_HALF_UP
from typing import Dict, List

from .models import Order, Product, Quote, QuoteLine

_CTX = Context(prec=100000, rounding=ROUND_HALF_UP, Emax=999999999, Emin=-999999999)
_RATES = {"standard": 20, "reduced": 5, "zero": 0}


def _pct(pence: int, percent: int) -> int:
    """percent of pence, rounded half up (pence >= 0)."""
    return (pence * percent + 50) // 100


def _money(pence: int) -> Decimal:
    return _CTX.scaleb(Decimal(pence), -2)


def allocate_discount(discount: int, nets: List[int]) -> List[int]:
    """Share `discount` pence over lines in proportion to `nets` (pence): each
    share rounds down, leftover pence go to the biggest fractional losses,
    earlier line first on a tie."""
    total = sum(nets)
    if not discount or not total:
        return [0] * len(nets)
    parts = [divmod(discount * net, total) for net in nets]
    shares = [p[0] for p in parts]
    leftover = discount - sum(shares)
    for i in sorted(range(len(nets)), key=lambda i: (-parts[i][1], i))[:leftover]:
        shares[i] += 1
    return shares


def price_order(order: Order, catalog: Dict[str, Product]) -> Quote:
    rows = []  # (sku, qty, unit, gross, discount, net) in pence
    for sku, qty in order.lines:
        product = catalog[sku]
        unit = int(_CTX.multiply(product.price, 100))
        gross = qty * unit
        percent = 10 if qty >= 50 else 5 if qty >= 10 else 0
        discount = _pct(gross, percent)
        rows.append((sku, qty, unit, gross, discount, gross - discount))

    subtotal = sum(r[5] for r in rows)
    order_discount = _pct(subtotal, 3) if subtotal >= 50000 else 0

    shares = allocate_discount(order_discount, [r[5] for r in rows])

    tax = 0
    for row, share in zip(rows, shares):
        tax += _pct(row[5] - share, _RATES[catalog[row[0]].tax])

    lines = [
        QuoteLine(sku, qty, _money(unit), _money(gross), _money(-discount), _money(net))
        for sku, qty, unit, gross, discount, net in rows
    ]  # type: List[QuoteLine]
    return Quote(
        lines,
        _money(subtotal),
        _money(-order_discount),
        _money(tax),
        _money(subtotal - order_discount + tax),
    )
